transposed_convolution_cuda_source = """
torch::Tensor transposed_convolution_cuda(
    torch::Tensor input_,
    int batch_size,
    int in_channels,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    bool bias
) {
    // Compute the length of the output along the "length" dimension.
    int input_len = input_.size(2);
    int out_len = (input_len + 2*padding - kernel_size) * stride + output_padding;

    auto conv = torch::conv_transpose1d(input_, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias);
    return conv;
}
"""

